"""Notification operations backed by MongoDB.

See ``backend/docs/notifications.md`` for the full design. Two generation
paths:

* **Event-driven** (``booking_approved``, ``inbody_added``): callers insert a
  notification synchronously, inline in the existing write path
  (``booking_service.set_booking_status`` / ``admin_assign_booking``,
  ``api/admin.py::add_inbody``).
* **Time-based** (``session_reminder``): generated by a background scheduler
  (see ``services/notification_scheduler.py``) that periodically scans for
  soon-to-start approved bookings.

Idempotency: at most one notification per ``(type, related_id)`` pair, enforced
by a unique index (``notification_type_related_unique``) — ``create_notification``
treats a duplicate-key error as "already notified", not a failure.
"""

import uuid
from datetime import datetime, timezone
from typing import Any

from pymongo.errors import DuplicateKeyError

from src.db.mongo import notifications_collection, trainer_notifications_collection
from src.schema.notification import (
    Notification,
    NotificationType,
    TrainerNotification,
    TrainerNotificationType,
)

# ── Copy templates (Vietnamese, matches api-guidelines tone) ────────────────

_TITLES: dict[NotificationType, str] = {
    NotificationType.BOOKING_APPROVED: "Lịch tập đã được xác nhận",
    NotificationType.SESSION_REMINDER: "Buổi tập sắp bắt đầu",
    NotificationType.INBODY_ADDED: "Có chỉ số InBody mới",
}

# Click-through targets — parsed by the frontend as "page:tab".
_TARGETS: dict[NotificationType, str] = {
    NotificationType.BOOKING_APPROVED: "dashboard:bookings",
    NotificationType.SESSION_REMINDER: "dashboard:bookings",
    NotificationType.INBODY_ADDED: "dashboard:overview",
}

_TRAINER_TITLES: dict[TrainerNotificationType, str] = {
    TrainerNotificationType.BOOKING_CREATED: "Có lịch tập mới",
    TrainerNotificationType.BOOKING_CANCELLED: "Lịch tập đã bị hủy",
    TrainerNotificationType.TRAINEE_REGISTERED: "Hội viên mới đăng ký",
}

_TRAINER_TARGETS: dict[TrainerNotificationType, str] = {
    TrainerNotificationType.BOOKING_CREATED: "admin:bookings",
    TrainerNotificationType.BOOKING_CANCELLED: "admin:bookings",
    TrainerNotificationType.TRAINEE_REGISTERED: "admin:clients",
}


def _now() -> datetime:
    return datetime.now(tz=timezone.utc)


def _slot_label(time_key: str) -> str:
    """'2026-07-16T08:00' -> '08:00 16/07' for human-readable messages."""
    date_part, _, hour_part = time_key.partition("T")
    if not date_part or not hour_part:
        return time_key
    parts = date_part.split("-")
    if len(parts) != 3:
        return time_key
    _, month, day = parts
    return f"{hour_part[:5]} {day}/{month}"


def create_notification(
    *,
    customer_id: str,
    type: NotificationType,
    related_id: str,
    message: str,
    title: str | None = None,
    target: str | None = None,
) -> dict[str, Any]:
    """Insert a notification; silently no-ops if one already exists for
    this ``(type, related_id)`` pair (idempotent — see module docstring).
    """
    name = customer_id.strip()
    if not name:
        return {"success": False, "message": "customer_id is required"}
    if not related_id.strip():
        return {"success": False, "message": "related_id is required"}

    notification = Notification(
        id=str(uuid.uuid4()),
        customer_id=name,
        type=type,
        title=title or _TITLES[type],
        message=message,
        target=target or _TARGETS[type],
        related_id=related_id.strip(),
        read=False,
        created_at=_now(),
    )
    payload = notification.model_dump()
    payload["type"] = type.value

    try:
        notifications_collection().insert_one(payload)
    except DuplicateKeyError:
        return {"success": True, "created": False, "message": "Already notified"}

    # Send push notification (best-effort)
    try:
        from src.services.push_service import send_to_customer
        send_to_customer(
            customer_id=name,
            title=title or _TITLES[type],
            body=message,
        )
    except Exception:
        pass  # Push is fire-and-forget

    return {"success": True, "created": True, "notification_id": notification.id}


def notify_booking_approved(*, customer_id: str, booking_id: str, time_key: str) -> dict[str, Any]:
    return create_notification(
        customer_id=customer_id,
        type=NotificationType.BOOKING_APPROVED,
        related_id=booking_id,
        message=f"Buổi tập {_slot_label(time_key)} đã được HLV xác nhận.",
    )


def notify_session_reminder(*, customer_id: str, booking_id: str, time_key: str) -> dict[str, Any]:
    return create_notification(
        customer_id=customer_id,
        type=NotificationType.SESSION_REMINDER,
        related_id=booking_id,
        message=f"Buổi tập của bạn bắt đầu trong 1 giờ ({_slot_label(time_key)}).",
    )


def notify_inbody_added(*, customer_id: str, inbody_id: str, date_recorded: str) -> dict[str, Any]:
    return create_notification(
        customer_id=customer_id,
        type=NotificationType.INBODY_ADDED,
        related_id=inbody_id,
        message=f"HLV đã cập nhật chỉ số InBody ngày {date_recorded} cho bạn.",
    )


def retract_session_reminder(*, booking_id: str) -> dict[str, Any]:
    """Delete a pending session_reminder for a booking that was cancelled
    (§3.2 of the design doc) — a reminder should never linger for a slot
    that no longer exists.
    """
    result = notifications_collection().delete_one(
        {"type": NotificationType.SESSION_REMINDER.value, "related_id": booking_id}
    )
    return {"success": True, "deleted": result.deleted_count > 0}


# ── Read paths (customer-facing API) ────────────────────────────────────────

def _to_dict(doc: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": doc.get("id", ""),
        "customer_id": doc.get("customer_id", ""),
        "type": doc.get("type", ""),
        "title": doc.get("title", ""),
        "message": doc.get("message", ""),
        "target": doc.get("target", ""),
        "related_id": doc.get("related_id", ""),
        "read": bool(doc.get("read", False)),
        "created_at": str(doc.get("created_at", "")),
        "read_at": str(doc["read_at"]) if doc.get("read_at") else None,
    }


def list_notifications(
    *, customer_id: str, unread_only: bool = False, limit: int = 50
) -> list[dict[str, Any]]:
    name = customer_id.strip()
    if not name:
        return []

    query: dict[str, Any] = {"customer_id": name}
    if unread_only:
        query["read"] = False

    docs = (
        notifications_collection()
        .find(query, {"_id": 0})
        .sort("created_at", -1)
        .limit(limit)
    )
    return [_to_dict(doc) for doc in docs]


def unread_count(*, customer_id: str) -> int:
    name = customer_id.strip()
    if not name:
        return 0
    return notifications_collection().count_documents(
        {"customer_id": name, "read": False}
    )


def mark_read(*, notification_id: str, customer_id: str) -> dict[str, Any]:
    coll = notifications_collection()
    doc = coll.find_one({"id": notification_id, "customer_id": customer_id.strip()})
    if doc is None:
        return {"success": False, "message": "Không tìm thấy thông báo."}
    coll.update_one(
        {"_id": doc["_id"]}, {"$set": {"read": True, "read_at": _now()}}
    )
    return {"success": True}


def mark_all_read(*, customer_id: str) -> dict[str, Any]:
    name = customer_id.strip()
    if not name:
        return {"success": False, "message": "customer_id is required"}
    result = notifications_collection().update_many(
        {"customer_id": name, "read": False},
        {"$set": {"read": True, "read_at": _now()}},
    )
    return {"success": True, "updated": result.modified_count}


# ── Trainer-facing notifications (broadcast — see schema/notification.py) ──

def create_trainer_notification(
    *,
    type: TrainerNotificationType,
    related_id: str,
    message: str,
    title: str | None = None,
    target: str | None = None,
) -> dict[str, Any]:
    """Insert a trainer-facing notification; idempotent per ``(type, related_id)``
    just like the customer-facing ``create_notification`` (see its docstring).
    """
    if not related_id.strip():
        return {"success": False, "message": "related_id is required"}

    notification = TrainerNotification(
        id=str(uuid.uuid4()),
        type=type,
        title=title or _TRAINER_TITLES[type],
        message=message,
        target=target or _TRAINER_TARGETS[type],
        related_id=related_id.strip(),
        read=False,
        created_at=_now(),
    )
    payload = notification.model_dump()
    payload["type"] = type.value

    try:
        trainer_notifications_collection().insert_one(payload)
    except DuplicateKeyError:
        return {"success": True, "created": False, "message": "Already notified"}

    # Send push to trainers (best-effort)
    try:
        from src.services.push_service import send_to_trainers
        send_to_trainers(
            title=title or _TRAINER_TITLES[type],
            body=message,
        )
    except Exception:
        pass  # Push is fire-and-forget

    return {"success": True, "created": True, "notification_id": notification.id}


def notify_booking_created(*, customer_id: str, booking_id: str, time_key: str) -> dict[str, Any]:
    return create_trainer_notification(
        type=TrainerNotificationType.BOOKING_CREATED,
        related_id=booking_id,
        message=f"{customer_id} vừa đặt lịch tập {_slot_label(time_key)}.",
    )


def notify_booking_cancelled(*, customer_id: str, booking_id: str, time_key: str) -> dict[str, Any]:
    # Cancellation reuses the same booking_id — a prior booking_created
    # notification for it may already exist. Suffix the related_id so the
    # (type, related_id) idempotency key doesn't collide with that entry,
    # while still being unique per booking (not per cancellation attempt).
    return create_trainer_notification(
        type=TrainerNotificationType.BOOKING_CANCELLED,
        related_id=f"{booking_id}:cancelled",
        message=f"{customer_id} đã hủy lịch tập {_slot_label(time_key)}.",
    )


def notify_trainee_registered(*, customer_id: str) -> dict[str, Any]:
    return create_trainer_notification(
        type=TrainerNotificationType.TRAINEE_REGISTERED,
        related_id=customer_id,
        message=f"{customer_id} vừa đăng ký làm hội viên mới.",
    )


def notify_batch_booking(*, customer_id: str, count: int, related_id: str) -> dict[str, Any]:
    """Single summary notification for a batch booking (N slots assigned by PT)."""
    return create_notification(
        customer_id=customer_id,
        type=NotificationType.BOOKING_APPROVED,
        related_id=related_id,
        message=f"HLV đã đặt {count} buổi tập cho bạn.",
        title="Lịch tập mới từ HLV",
    )


def _trainer_to_dict(doc: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": doc.get("id", ""),
        "type": doc.get("type", ""),
        "title": doc.get("title", ""),
        "message": doc.get("message", ""),
        "target": doc.get("target", ""),
        "related_id": doc.get("related_id", ""),
        "read": bool(doc.get("read", False)),
        "created_at": str(doc.get("created_at", "")),
        "read_at": str(doc["read_at"]) if doc.get("read_at") else None,
    }


def list_trainer_notifications(
    *, unread_only: bool = False, limit: int = 50
) -> list[dict[str, Any]]:
    query: dict[str, Any] = {"read": False} if unread_only else {}
    docs = (
        trainer_notifications_collection()
        .find(query, {"_id": 0})
        .sort("created_at", -1)
        .limit(limit)
    )
    return [_trainer_to_dict(doc) for doc in docs]


def trainer_unread_count() -> int:
    return trainer_notifications_collection().count_documents({"read": False})


def mark_trainer_notification_read(*, notification_id: str) -> dict[str, Any]:
    coll = trainer_notifications_collection()
    doc = coll.find_one({"id": notification_id})
    if doc is None:
        return {"success": False, "message": "Không tìm thấy thông báo."}
    coll.update_one({"_id": doc["_id"]}, {"$set": {"read": True, "read_at": _now()}})
    return {"success": True}


def mark_all_trainer_notifications_read() -> dict[str, Any]:
    result = trainer_notifications_collection().update_many(
        {"read": False}, {"$set": {"read": True, "read_at": _now()}}
    )
    return {"success": True, "updated": result.modified_count}
